export default function PerfilAdmin() {
    const { currentUser, logout } = useContext(AuthContext);
    
    if (!currentUser) {
        return <div>Cargando perfil...</div>;
    }
    
    // Nombres de propiedades alternativos (ajusta según tu base de datos)
    const nombreCompleto = currentUser.nombre_completo || 
        `${currentUser.nom_1 || ''} ${currentUser.nom_2 || ''} ${currentUser.ape_1 || ''} ${currentUser.ape_2 || ''}`.trim() ||
        currentUser.nombre ||
        'No especificado';
    
    const telefono = currentUser.telefono || 
        currentUser.celular || 
        currentUser.phone || 
        'No especificado';
    
    const identificacion = currentUser.numero_documento || 
        currentUser.documento || 
        currentUser.id_usuario || 
        'No especificado';
    
    const tipoDocumento = currentUser.tipo_documento || 
        currentUser.t_doc || 
        '';
    
    return (
        <div className="perfil-page-container">
            <HeaderPerfil />
            
            <main>
                <section className="perfil-box">
                    <div className="profile-card">
                        <h2>Perfil</h2>
                        
                        <div className="profile-content">
                            {/* Imagen del perfil (tu código existente) */}
                            
                            <div className="info">
                                <h4>
                                    <strong>Nombre de usuario</strong><br />
                                    <span className="dato">{nombreCompleto || 'Administrador'}</span>
                                </h4>
                                
                                <h4>
                                    <strong>Correo electrónico</strong><br />
                                    <span className="dato">{currentUser.correo || 'No especificado'}</span>
                                </h4>
                                
                                <h4>
                                    <strong>Número telefónico</strong><br />
                                    <span className="dato">{telefono}</span>
                                </h4>
                                
                                <h4>
                                    <strong>Identificación</strong><br />
                                    <span className="dato">
                                        {tipoDocumento ? `${tipoDocumento} ` : ''}
                                        {identificacion}
                                    </span>
                                </h4>
                            </div>
                        </div>
                        
                        {/* Botones (tu código existente) */}
                    </div>
                </section>
            </main>
        </div>
    );
}
